export function escapeCSV(value) {
  return `"${String(value ?? "").replace(/"/g, '""')}"`;
}

export function getCsvFileName(datasetName) {
  return datasetName
    ? datasetName.replace(/\.\w+$/, ".csv")
    : "data.csv";
}
